examples.template:
Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    Row(
        modifier = Modifier.padding(horizontal = MonarchTheme.spacing.space4),
        horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        MonarchSelect(
            options = listOf(
                MonarchSelectOption("all", {{toolbar.filter}}),
                MonarchSelectOption("members", "Members"),
                MonarchSelectOption("security", "Security"),
                MonarchSelectOption("settings", "Settings"),
            ),
            selected = area,
            onSelect = { area = it },
            modifier = Modifier.weight(1f),
            contentDescription = "Area",
        )
        MonarchButton(
            text = {{toolbar.export}},
            onClick = { /* Download the CSV file. */ },
            variant = MonarchButtonVariant.Secondary,
            size = MonarchButtonSize.Sm,
        )
    }
    // Five short columns fit a phone when the table may narrow them below the 112dp default.
    CompositionLocalProvider(LocalMonarchDataTableMinColumnWidth provides 48.dp) {
    MonarchDataTable(
        caption = "Audit log",
        rows = shown,
        columns = listOf<MonarchDataTableColumn<AuditEvent>>(
            MonarchDataTableColumn(
                "Time",
                id = "time",
                sortable = false,
                weight = 1.3f,
                cell = { event ->
                    MonarchText(
                        text = timeFormat.format(Instant.ofEpochMilli(event.time)),
                        style = MonarchTextStyle.Caption,
                        color = MonarchTheme.colors.textMuted,
                    )
                },
            ) { timeFormat.format(Instant.ofEpochMilli(it.time)) },
            MonarchDataTableColumn(
                "Actor",
                id = "actor",
                sortable = false,
                weight = 1.5f,
                cell = { event ->
                    // The avatar over the name: a phone column is too narrow for them side by side.
                    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
                        MonarchAvatar(image = null, name = event.actor, size = MonarchAvatarSize.Sm, decorative = true)
                        MonarchText(text = event.actor, style = MonarchTextStyle.Label)
                        event.kind?.let { MonarchBadge(text = kindLabel(it), variant = MonarchBadgeVariant.Outline) }
                    }
                },
            ) { event -> listOfNotNull(event.actor, event.kind?.let(::kindLabel)).joinToString(" · ") },
            MonarchDataTableColumn(
                "Action",
                id = "action",
                sortable = false,
                weight = 1.5f,
                cell = { event ->
                    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
                        MonarchText(text = event.action, style = MonarchTextStyle.Caption)
                        event.source?.let { MonarchBadge(text = it) }
                    }
                },
            ) { event -> listOfNotNull(event.action, event.source).joinToString("\n") },
            MonarchDataTableColumn(
                "Target",
                id = "target",
                sortable = false,
                weight = 1.15f,
                cell = { event -> MonarchText(text = event.target ?: "—", style = MonarchTextStyle.Caption) },
            ) { it.target.orEmpty() },
            MonarchDataTableColumn(
                "Details",
                id = "details",
                sortable = false,
                weight = 1.1f,
                cell = { MonarchText(text = "Details", style = MonarchTextStyle.Caption) },
            ) { "Details" },
        ),
        rowKey = { it.id },
        layout = MonarchDataTableLayout.Table,
        sortsRows = false,
        onOpen = { openId = it.id },
        footer = {
            Row(
                modifier = Modifier.fillMaxWidth().padding(MonarchTheme.spacing.space3),
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3, Alignment.CenterHorizontally),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                MonarchText(text = "Showing ${shown.size} events", style = MonarchTextStyle.Caption)
                MonarchButton(
                    text = "Load more",
                    onClick = { /* Load the next page with the cursor. */ },
                    variant = MonarchButtonVariant.Secondary,
                    size = MonarchButtonSize.Sm,
                )
            }
        },
    )
    }
}
events.firstOrNull { it.id == openId }?.let { event ->
    MonarchBottomSheet(onDismissRequest = { openId = null }, title = "Event details") {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchDescriptionList(
                items = listOf(
                    MonarchDescriptionItem("Time", timeFormat.format(Instant.ofEpochMilli(event.time))),
                    MonarchDescriptionItem("Actor", listOfNotNull(event.actor, event.kind?.let(::kindLabel)).joinToString(" · ")),
                    MonarchDescriptionItem("Action", event.action),
                    MonarchDescriptionItem("Target", event.target.orEmpty()),
                ),
            )
            MonarchButton(text = "Close", onClick = { openId = null }, modifier = Modifier.fillMaxWidth())
        }
    }
}

